mkitem!{mkenum!{# [doc = " Formatted parts."] # [derive (Copy , Clone , PartialEq , Eq , Debug)] pub enum Part < 'a > { # [doc = " Given number of zero digits."] Zero (usize) , # [doc = " A literal number up to 5 digits."] Num (u16) , # [doc = " A verbatim copy of given bytes."] Copy (& 'a [u8]) , }}}
mkitem!{mkimpl!{impl < 'a > Part < 'a > { # [doc = " Returns the exact byte length of given part."] pub fn len (& self) -> usize { match * self { Part :: Zero (nzeroes) => nzeroes , Part :: Num (v) => v . checked_ilog10 () . unwrap_or_default () as usize + 1 , Part :: Copy (buf) => buf . len () , } } # [doc = " Writes a part into the supplied buffer."] # [doc = " Returns the number of written bytes, or `None` if the buffer is not enough."] # [doc = " (It may still leave partially written bytes in the buffer; do not rely on that.)"] pub fn write (& self , out : & mut [u8]) -> Option < usize > { let len = self . len () ; if out . len () >= len { match * self { Part :: Zero (nzeroes) => { for c in & mut out [.. nzeroes] { * c = b'0' ; } } Part :: Num (mut v) => { for c in out [.. len] . iter_mut () . rev () { * c = b'0' + (v % 10) as u8 ; v /= 10 ; } } Part :: Copy (buf) => { out [.. buf . len ()] . copy_from_slice (buf) ; } } Some (len) } else { None } } }}}
mkitem!{mkstruct!{# [doc = " Formatted result containing one or more parts."] # [doc = " This can be written to the byte buffer or converted to the allocated string."] # [allow (missing_debug_implementations)] # [derive (Clone)] pub struct Formatted < 'a > { # [doc = " A byte slice representing a sign, either `\"\"`, `\"-\"` or `\"+\"`."] pub sign : & 'static str , # [doc = " Formatted parts to be rendered after a sign and optional zero padding."] pub parts : & 'a [Part < 'a >] , }}}
mkitem!{mkimpl!{impl < 'a > Formatted < 'a > { # [doc = " Returns the exact byte length of combined formatted result."] pub fn len (& self) -> usize { self . sign . len () + self . parts . iter () . map (| part | part . len ()) . sum :: < usize > () } # [doc = " Writes all formatted parts into the supplied buffer."] # [doc = " Returns the number of written bytes, or `None` if the buffer is not enough."] # [doc = " (It may still leave partially written bytes in the buffer; do not rely on that.)"] pub fn write (& self , out : & mut [u8]) -> Option < usize > { out . get_mut (.. self . sign . len ()) ? . copy_from_slice (self . sign . as_bytes ()) ; let mut written = self . sign . len () ; for part in self . parts { let len = part . write (& mut out [written ..]) ? ; written += len ; } Some (written) } }}}